<a class="enlace-volver" href="/consultas">&larr; Volver a consultas</a><section class="titulo-vista"><div><p class="sobretitulo">REGISTRO CLINICO</p><h1><?= $idRegistro?'Editar consulta':'Registrar consulta' ?></h1><p>La informacion guardada estara disponible para el paciente y sus medicos autorizados.</p></div></section>
<p id="mensaje-carga" class="mensaje" role="status" hidden></p><section class="tarjeta formulario-ancho"><dl class="datos-paciente" id="resumen-consulta"></dl><form id="formulario-consulta" hidden>
<label>Motivo de consulta<textarea name="motivoConsulta" rows="3" maxlength="1000" required></textarea></label><label>Diagnostico<textarea name="diagnostico" rows="4" maxlength="5000" required></textarea></label><label>Observaciones compartidas con el paciente<textarea name="observaciones" rows="3" maxlength="5000"></textarea></label>
<div class="cabecera-seccion"><h2>Tratamientos</h2><button id="agregar-tratamiento" type="button" class="boton boton-secundario">Agregar tratamiento</button></div><p class="ayuda">Opcional. Hasta 20 tratamientos.</p><div id="tratamientos"></div>
<p id="mensaje-formulario" class="mensaje" role="status" hidden></p><div class="acciones"><button type="submit" class="boton">Guardar consulta</button><a href="/consultas" class="boton boton-secundario">Volver</a></div></form></section>
<template id="plantilla-tratamiento"><fieldset class="tratamiento-formulario"><legend>Tratamiento</legend><div class="rejilla-formulario"><label>Medicamento o intervencion<input data-campo="medicamento" maxlength="150" required></label><label>Dosis<input data-campo="dosis" maxlength="100" required></label><label>Frecuencia<input data-campo="frecuencia" maxlength="100" required></label><label>Duracion<input data-campo="duracion" maxlength="100" required></label></div><label>Indicaciones<textarea data-campo="indicaciones" rows="2" maxlength="1000"></textarea></label><button class="boton boton-secundario quitar-tratamiento" type="button">Quitar tratamiento</button></fieldset></template>
